ROLE_IDS = [f"11111111-b14b-4000-8000-00000000000{i}" for i in (1, 2, 3)]
ACTIONS = ["exam.parse.start", "exam.parse.read"]
OPERATOR = [
    "exam.script.read",
    "exam.script.edit",
    "exam.script.confirm",
    "exam.identity.verify",
    "scan.batch.create",
    "scan.batch.read",
    "scan.file.upload",
    "scan.file.read",
    "exam.roster.read",
    *ACTIONS,
]


def install_security():
    for statement in GUARDS.strip().split(";\nCREATE FUNCTION"):
        op.execute(
            statement if statement.startswith("CREATE FUNCTION") else "CREATE FUNCTION" + statement
        )
    for table, function, events in [
        ("exam_parsing_jobs", "guard_exam_parse_job", "INSERT OR UPDATE OR DELETE"),
        ("exam_submission_links", "guard_exam_submission_link", "INSERT OR UPDATE OR DELETE"),
        ("exam_parsing_operations", "guard_security_immutable", "UPDATE OR DELETE"),
    ]:
        op.execute(
            f"CREATE TRIGGER protect_exam_parse BEFORE {events} ON {table} "
            f"FOR EACH ROW EXECUTE FUNCTION {function}()"
        )
    db = op.get_bind()
    for code in ACTIONS:
        db.execute(
            sa.text(
                "INSERT INTO permission_definitions VALUES "
                "(:code,true,ARRAY['installation','exam_event','exam_session'])"
            ),
            dict(code=code),
        )
    for rid, name, codes in zip(
        ROLE_IDS,
        ["exam_parse_operator", "exam_parse_deployer", "exam_parse_reader"],
        [
            OPERATOR,
            ["security.grants.manage", *OPERATOR],
            ["exam.parse.read", "exam.script.read", "exam.identity.verify", "exam.roster.read"],
        ],
        strict=True,
    ):
        db.execute(
            sa.text("INSERT INTO security_role_versions VALUES (CAST(:id AS uuid),:name,1,NULL)"),
            dict(id=rid, name=name),
        )
        for code in codes:
            db.execute(
                sa.text("INSERT INTO security_role_permissions VALUES (CAST(:id AS uuid),:code)"),
                dict(id=rid, code=code),
            )
        db.execute(
            sa.text(
                "UPDATE security_role_versions SET sealed_at=clock_timestamp() "
                "WHERE id=CAST(:id AS uuid)"
            ),
            dict(id=rid),
        )


def remove_security():
    op.execute(
        "LOCK TABLE exam_parsing_jobs,exam_submission_links,exam_parsing_operations,"
        "security_grants IN ACCESS EXCLUSIVE MODE"
    )
    db = op.get_bind()
    for table in ["exam_parsing_jobs", "exam_submission_links", "exam_parsing_operations"]:
        if db.scalar(sa.text(f"SELECT EXISTS(SELECT 1 FROM {table})")):
            raise RuntimeError("exam_parse_downgrade_requires_archived_data")
    if db.scalar(
        sa.text(
            "SELECT EXISTS(SELECT 1 FROM security_grants WHERE "
            "role_version_id=ANY(CAST(:ids AS uuid[])))"
        ),
        dict(ids=ROLE_IDS),
    ):
        raise RuntimeError("exam_parse_downgrade_requires_archived_grants")
    for table in ["exam_parsing_jobs", "exam_submission_links", "exam_parsing_operations"]:
        op.execute(f"DROP TRIGGER protect_exam_parse ON {table}")
    op.execute("DROP FUNCTION guard_exam_parse_job()")
    op.execute("DROP FUNCTION guard_exam_submission_link()")
    op.execute(
        "ALTER TABLE security_role_permissions DISABLE TRIGGER immutable_security_role_permissions"
    )
    op.execute("ALTER TABLE security_role_versions DISABLE TRIGGER immutable_security_role")
    for rid in ROLE_IDS:
        db.execute(
            sa.text(
                "DELETE FROM security_role_permissions WHERE role_version_id=CAST(:id AS uuid)"
            ),
            dict(id=rid),
        )
        db.execute(
            sa.text("DELETE FROM security_role_versions WHERE id=CAST(:id AS uuid)"), dict(id=rid)
        )
    op.execute(
        "ALTER TABLE security_role_permissions ENABLE TRIGGER immutable_security_role_permissions"
    )
    op.execute("ALTER TABLE security_role_versions ENABLE TRIGGER immutable_security_role")
    for code in ACTIONS:
        db.execute(sa.text("DELETE FROM permission_definitions WHERE code=:code"), dict(code=code))
